import mpmath, functools

def div(x,y):
  if 0==y:
    return 0
  else:
    return x/y

def Qh(f,a=0,b=1,h=1/64.0,wanna_print=True,K=10):
  @functools.cache
  def E(x,p=mpmath.mp.dps):
    return mpmath.exp(-mpmath.exp(x*(1+mpmath.exp(-x))))
  @functools.cache
  def Ep(x,p=mpmath.mp.dps):
    return mpmath.exp(-mpmath.exp(x*(1+mpmath.exp(-x))))*mpmath.exp(x*(1+mpmath.exp(-x)))*(1+(1-x)*mpmath.exp(-x))
  def id(x):
    if -mpmath.inf<a and a<mpmath.inf:
      return x
    else:
      return 0
  if a==b:
    return 0
  if a>b:
    return -Qh(f,b,a,h,wanna_print,K)
  if a==-mpmath.inf and b==mpmath.inf:
    return Qh(lambda x:f(div(x,(1-x**2)))*div((1+x**2),(1-x**2)**2),-1,1,h,wanna_print,K)
  if -mpmath.inf<a and a<mpmath.inf and b==mpmath.inf:
    return Qh(lambda x:div(f(a+div(x,(1-x))),(1-x)**2),0,1,h,wanna_print,K)
  if a==-mpmath.inf and -mpmath.inf<b and b<mpmath.inf:
    return Qh(lambda x:div(f(b-div(x,(1-x))),(1-x)**2),0,1,h,wanna_print,K)
  ba=b-a ; p=mpmath.mp.dps
  g=lambda x:ba*id(f(a+ba*E(x,p))*Ep(x,p))
  S=h*g(0)
  n=-1 ; x=-h ; SS=S+h*g(x)
  while SS!=S or n>-K:
    n -= 1 ; x -= h ; S=SS ; SS += h*g(x)
  N=-n
  n=1 ; x=h ; SS=S+h*g(x)
  while SS!=S or n<K:
    n += 1 ; x += h ; S=SS ; SS += h*g(x)
  N += n+1
  if wanna_print: print("N=",N)
  return S

